@Testcontainers class JdbcCouponInventoryTest {
 @Container static MySQLContainer<?> mysql=new MySQLContainer<>("mysql:8.0").withCommand("--log-bin-trust-function-creators=1");static JdbcTemplate jdbc;final ObjectMapper json=new ObjectMapper();ReservationStore db;CouponInventory coupons;MerchantActor merchant,other;VehicleOwner owner,peer;OperatorActor operator;
 static class Time extends Clock {volatile Instant value=Instant.now().truncatedTo(java.time.temporal.ChronoUnit.SECONDS);public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId z){return Clock.fixed(value,z);}public Instant instant(){return value;}}Time clock;
 @BeforeAll static void schema()throws Exception{var ds=new DriverManagerDataSource(mysql.getJdbcUrl(),mysql.getUsername(),mysql.getPassword());jdbc=new JdbcTemplate(ds);try(var c=ds.getConnection();var paths=Files.list(Path.of("..","docs","sql","migrations"))){for(var p:paths.filter(p->p.toString().endsWith(".sql")).sorted().toList())ScriptUtils.executeSqlScript(c,new FileSystemResource(p));ScriptUtils.executeSqlScript(c,new FileSystemResource(Path.of("..","docs","sql","migrations","V038__coupon_inventory_and_claims.sql")));}}
 @BeforeEach void setup(){jdbc.execute("DROP TRIGGER IF EXISTS fail_coupon_audit");for(String t:List.of("coupon_stock_event","coupon_issue","coupon_publication","coupon_source","user_coupon","coupon","merchant_project","standard_project","staff_account","merchant","user","operator_account","auth_session","audit_log","idempotency_record"))jdbc.update("DELETE FROM `"+t+"`");clock=new Time();var manager=new DataSourceTransactionManager(jdbc.getDataSource());db=new ReservationStore(jdbc,json,new WriteIntegrityService(jdbc,json,manager),clock,manager);coupons=new CouponInventory(db,new OperatorIdentity(jdbc,null,manager));jdbc.update("INSERT INTO merchant(id,merchant_type,name,address,status) VALUES(1,2,'synthetic-A','test',1),(2,2,'synthetic-B','test',1)");jdbc.update("INSERT INTO staff_account(id,merchant_id,role,account,status) VALUES(1,1,'MERCHANT','coupon-A','ACTIVE'),(2,2,'MERCHANT','coupon-B','ACTIVE')");jdbc.update("INSERT INTO user(id,openid,status) VALUES(1,'coupon-owner',1),(2,'coupon-peer',1)");jdbc.update("INSERT INTO operator_account(id,account,password_hash,phone,can_coupon) VALUES(1,'coupon-operator','unused','13800000000',1)");jdbc.update("INSERT INTO standard_project(id,category,project_name,service_content,base_price_low,base_price_high,status) VALUES(1,1,'synthetic-project','synthetic',10,20,1)");jdbc.update("INSERT INTO merchant_project(id,merchant_id,project_id,price,on_shelf) VALUES(1,1,1,12.34,1),(2,2,1,12.34,1)");merchant=new MerchantActor(1,1,session(1,"staff_account","MERCHANT","merchant-account",1L),Instant.now().plusSeconds(3600));other=new MerchantActor(2,2,session(2,"staff_account","MERCHANT","merchant-account",2L),Instant.now().plusSeconds(3600));owner=new VehicleOwner(1,session(1,"user","OWNER","test-app",null),Instant.now().plusSeconds(3600));peer=new VehicleOwner(2,session(2,"user","OWNER","test-app",null),Instant.now().plusSeconds(3600));operator=new OperatorActor(1,session(1,"operator_account","OPERATOR",OperatorActor.APP,null),Instant.now().plusSeconds(3600));}
 String key(){return UUID.randomUUID().toString();}String session(long id,String type,String role,String app,Long shop){String s=key();jdbc.update("INSERT INTO auth_session(id,subject_type,subject_id,role,app_id,merchant_id,refresh_hash,expires_at) VALUES(?,?,?,?,?,?,?,DATE_ADD(UTC_TIMESTAMP(),INTERVAL 1 HOUR))",s,type,id,role,app,shop,key());return s;}
 ObjectNode terms(int quantity){return json.createObjectNode().put("name","合成测试券").put("type","DISCOUNT").put("project_id",1).put("amount","5.00").put("min_spend","10.00").put("total_quantity",quantity).put("valid_from",clock.value.minusSeconds(60).toString()).put("valid_to",clock.value.plusSeconds(3600).toString());}
 ObjectNode draft(int stock){var b=json.createObjectNode();b.set("terms",terms(stock));return b;}long create(int stock){return coupons.create(merchant,key(),draft(stock)).path("data").path("coupon_id").longValue();}
 JsonNode statusBody(long revision,String status){return json.createObjectNode().put("expected_revision",revision).put("status",status);}long publish(int stock){long id=create(stock);coupons.status(merchant,id,key(),statusBody(1,"PUBLISHED"));return id;}
 JsonNode claimBody(long id){return json.createObjectNode().put("coupon_id",id).put("publication_revision",2);}int code(Runnable r){return assertThrows(ResponseStatusException.class,r::run).getStatusCode().value();}int count(String t){return jdbc.queryForObject("SELECT COUNT(*) FROM `"+t+"`",Integer.class);}
 @Test void oneClaimHasFrozenEvidenceStockAndAudit(){long id=publish(2);String k=key();var body=claimBody(id);var receipt=coupons.claim(owner,k,body);assertEquals(receipt,coupons.claim(owner,k,body));assertEquals(409,code(()->coupons.claim(owner,key(),body)));assertEquals(1,count("user_coupon"));assertEquals(1,count("coupon_issue"));assertEquals(1,count("coupon_stock_event"));assertEquals(3,count("audit_log"));assertEquals(1,jdbc.queryForObject("SELECT issued_quantity FROM coupon WHERE id=?",Integer.class,id));var mine=(List<?>)coupons.mine(owner,1,20).get("items");assertEquals("AVAILABLE",((Map<?,?>)mine.get(0)).get("availability"));assertTrue((Boolean)((Map<?,?>)mine.get(0)).get("source_known"));assertEquals(0L,coupons.mine(peer,1,20).get("total"));}
 @Test void finalStockReplaySucceedsAndOtherUserCannotClaim(){long id=publish(1);String k=key();var body=claimBody(id);var r=coupons.claim(owner,k,body);assertEquals(r,coupons.claim(owner,k,body));assertEquals(409,code(()->coupons.claim(peer,key(),body)));assertEquals(0L,coupons.offers(peer,1L,1,20).get("total"));}
 @Test void lastStockConcurrentHasOneWinner()throws Exception{long id=publish(1);race(List.of(()->coupons.claim(owner,key(),claimBody(id)),()->coupons.claim(peer,key(),claimBody(id))));assertEquals(1,count("coupon_issue"));assertEquals(1,count("coupon_stock_event"));}
 @Test void sameOwnerConcurrentDifferentKeysHasOneWinner()throws Exception{long id=publish(2);race(List.of(()->coupons.claim(owner,key(),claimBody(id)),()->coupons.claim(owner,key(),claimBody(id))));assertEquals(1,jdbc.queryForObject("SELECT issued_quantity FROM coupon WHERE id=?",Integer.class,id));}
 void race(List<Runnable> tasks)throws Exception{var start=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);try{var fs=new ArrayList<Future<Integer>>();for(var r:tasks)fs.add(pool.submit(()->{start.await();try{r.run();return 200;}catch(ResponseStatusException e){return e.getStatusCode().value();}}));start.countDown();var codes=new ArrayList<Integer>();for(var f:fs)codes.add(f.get(30,TimeUnit.SECONDS));Collections.sort(codes);assertEquals(List.of(200,409),codes);}finally{pool.shutdownNow();}}
 @Test void strictIdempotencyBodiesAndRevokedOwnerDeniedOnReplay(){long id=publish(2);String k=key();var body=claimBody(id);coupons.claim(owner,k,body);var different=((ObjectNode)body).deepCopy().put("publication_revision",3);assertEquals(409,code(()->coupons.claim(owner,k,different)));jdbc.update("UPDATE auth_session SET revoked_at=UTC_TIMESTAMP() WHERE id=?",owner.session());assertEquals(401,code(()->coupons.claim(owner,k,body)));assertEquals(1,count("coupon_issue"));}
 @Test void changedClaimBodyWithAnotherValidCouponRejected(){long a=publish(2),b=publish(2);String k=key();coupons.claim(owner,k,claimBody(a));assertEquals(400,code(()->coupons.claim(owner,k,claimBody(b))));assertEquals(1,count("coupon_issue"));}
 @Test void shopProjectExpiryAndStopPreventNewIssuanceAndReplay(){long id=publish(3);String k=key();coupons.claim(owner,k,claimBody(id));jdbc.update("UPDATE merchant_project SET on_shelf=0 WHERE id=1");assertEquals(404,code(()->coupons.claim(peer,key(),claimBody(id))));assertEquals(404,code(()->coupons.claim(owner,k,claimBody(id))));jdbc.update("UPDATE merchant_project SET on_shelf=1 WHERE id=1");clock.value=clock.value.plusSeconds(3600);assertEquals(409,code(()->coupons.claim(peer,key(),claimBody(id))));clock.value=clock.value.minusSeconds(3600);coupons.status(merchant,id,key(),statusBody(2,"STOPPED"));assertEquals(409,code(()->coupons.claim(peer,key(),claimBody(id))));var item=(Map<?,?>)((List<?>)coupons.mine(owner,1,20).get("items")).get(0);assertEquals("AVAILABLE",item.get("availability"));assertEquals(1,count("coupon_issue"));}
 @Test void futureCouponsNotClaimable(){var b=draft(1);((ObjectNode)b.get("terms")).put("valid_from",clock.value.plusSeconds(300).toString());long id=coupons.create(merchant,key(),b).path("data").path("coupon_id").longValue();coupons.status(merchant,id,key(),statusBody(1,"PUBLISHED"));assertEquals(409,code(()->coupons.claim(owner,key(),claimBody(id))));assertEquals(0L,coupons.offers(owner,1L,1,20).get("total"));}
 @Test void publishedImmutableCasAndCrossShopDenied(){long id=create(2);assertEquals(404,code(()->coupons.status(other,id,key(),statusBody(1,"PUBLISHED"))));var b=draft(3).put("expected_revision",1);coupons.update(merchant,id,key(),b);assertEquals(409,code(()->coupons.update(merchant,id,key(),b)));coupons.status(merchant,id,key(),statusBody(2,"PUBLISHED"));assertEquals(409,code(()->coupons.update(merchant,id,key(),draft(4).put("expected_revision",3))));assertEquals(409,code(()->coupons.status(merchant,id,key(),statusBody(3,"PUBLISHED"))));}
 @Test void staffCannotManageCoupon(){var staff=new MerchantActor(merchant.staffId(),merchant.merchantId(),"STAFF",merchant.session(),merchant.expires());assertEquals(403,code(()->coupons.merchantList(staff,1,20)));assertEquals(403,code(()->coupons.create(staff,key(),draft(2))));}
 @Test void poolUsesIndependentCapabilityCasAndNoImplicitSelection(){long id=publish(2);assertEquals(0L,coupons.offers(owner,null,1,20).get("total"));assertEquals(1L,coupons.offers(owner,1L,1,20).get("total"));var b=json.createObjectNode().put("expected_pool_revision",0).put("selected",true);String k=key();var receipt=coupons.pool(operator,id,k,b);assertEquals(1L,coupons.offers(owner,null,1,20).get("total"));assertEquals(receipt,coupons.pool(operator,id,k,b));assertEquals(409,code(()->coupons.pool(operator,id,key(),b)));jdbc.update("UPDATE operator_account SET can_coupon=0,can_catalog=1,can_review=1,can_onboard=1");assertEquals(403,code(()->coupons.pool(operator,id,k,b)));assertEquals(403,code(()->coupons.poolList(operator,1,20)));}
 @Test void legacyAvailableCouponNeverHasTrustedSource(){jdbc.update("INSERT INTO coupon(id,merchant_id,name,amount,total_quantity,valid_from,valid_to,status) VALUES(900,1,'legacy',1,10,UTC_TIMESTAMP(),DATE_ADD(UTC_TIMESTAMP(),INTERVAL 1 DAY),'PUBLISHED')");jdbc.update("INSERT INTO user_coupon(user_id,coupon_id,status) VALUES(1,900,'AVAILABLE')");var item=(Map<?,?>)((List<?>)coupons.mine(owner,1,20).get("items")).get(0);assertEquals("UNKNOWN",item.get("availability"));assertFalse((Boolean)item.get("source_known"));assertNull(item.get("terms"));assertEquals(0L,coupons.offers(owner,1L,1,20).get("total"));assertEquals(404,code(()->coupons.claim(peer,key(),claimBody(900))));}
 @Test void auditFailureRollsBackAllIssuanceAndRetrySameKeyWorks(){long id=publish(2);String k=key();jdbc.execute("CREATE TRIGGER fail_coupon_audit BEFORE INSERT ON audit_log FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic rollback'");assertEquals(503,code(()->coupons.claim(owner,k,claimBody(id))));assertEquals(0,count("user_coupon"));assertEquals(0,count("coupon_issue"));assertEquals(0,count("coupon_stock_event"));assertEquals(0,jdbc.queryForObject("SELECT issued_quantity FROM coupon WHERE id=?",Integer.class,id));jdbc.execute("DROP TRIGGER fail_coupon_audit");coupons.claim(owner,k,claimBody(id));assertEquals(1,count("coupon_issue"));}
 @Test void mineExpiryAndIssuerDisabledAreExplicit(){long id=publish(2);coupons.claim(owner,key(),claimBody(id));jdbc.update("UPDATE merchant SET status=0 WHERE id=1");assertEquals("ISSUER_UNAVAILABLE",mineAvailability());clock.value=clock.value.plusSeconds(3600);assertEquals("EXPIRED",mineAvailability());}
 String mineAvailability(){return (String)((Map<?,?>)((List<?>)coupons.mine(owner,1,20).get("items")).get(0)).get("availability");}
 @Test void serviceVoucherHasZeroCashTermsAndFrozenPublication(){var b=draft(1);((ObjectNode)b.get("terms")).put("type","SERVICE").put("amount","0.00").put("min_spend","0.00");CouponInput.draft(b.toString(),false);long id=coupons.create(merchant,key(),b).path("data").path("coupon_id").longValue();coupons.status(merchant,id,key(),statusBody(1,"PUBLISHED"));coupons.claim(owner,key(),claimBody(id));assertEquals("SERVICE",json.valueToTree(coupons.mine(owner,1,20)).path("items").get(0).path("terms").path("type").asText());assertEquals(0,count("order"));}
}
